using namespace std;
int main(){ int n; cin>>n; vector<int> e(n); for(auto&x:e)cin>>x; vector<int> indeg(n,0); for(int x:e) if(x>=0) indeg[x]++;
  // Kahn: peel off nodes not on cycles; what remains are disjoint cycles
  queue<int> q; vector<bool> gone(n,false); for(int i=0;i<n;i++) if(!indeg[i]) q.push(i);
  while(!q.empty()){ int u=q.front(); q.pop(); gone[u]=true; if(e[u]>=0 && --indeg[e[u]]==0) q.push(e[u]); }
  long long best=-1; vector<bool> vis(n,false);
  for(int i=0;i<n;i++) if(!gone[i] && !vis[i]){ long long s=0; int u=i; while(!vis[u]){ vis[u]=true; s+=u; u=e[u]; } best=max(best,s); }
  cout<<best<<"\n"; }

